const maisakaToolSpecsJSON = "{\n  \"query_image_memory\": {\n    \"description\": \"查询当前聊天中关于某张图片的记忆。\",\n    \"name\": \"query_image_memory\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"component_path\": {\n          \"description\": \"消息内图片组件路径。\",\n          \"type\": \"string\"\n        },\n        \"limit\": {\n          \"default\": 8,\n          \"maximum\": 20,\n          \"minimum\": 1,\n          \"type\": \"integer\"\n        },\n        \"message_id\": {\n          \"description\": \"包含目标图片的消息 ID。\",\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [\n        \"message_id\",\n        \"component_path\"\n      ],\n      \"type\": \"object\"\n    }\n  },\n  \"query_person_profile\": {\n    \"description\": \"查询人物画像。当需要查询与某人的关系时使用。\",\n    \"name\": \"query_person_profile\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"limit\": {\n          \"default\": 8,\n          \"description\": \"证据上限。\",\n          \"type\": \"integer\"\n        },\n        \"person_id\": {\n          \"description\": \"内部人物ID；明确给出时填。\",\n          \"type\": \"string\"\n        },\n        \"person_name\": {\n          \"description\": \"名称/昵称/关键词；通常填这个。\",\n          \"type\": \"string\"\n        }\n      },\n      \"type\": \"object\"\n    }\n  },\n  \"read_tool_result\": {\n    \"description\": \"取回某次工具调用保存的原始结果。联网工具预览或超长结果的整理结论会附有编号（如 r3）；当你需要其中没有的细节时，用这个编号分段读取原文，或用 keyword 直接查找相关片段。已有内容够用时不需要调用。\",\n    \"name\": \"read_tool_result\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"keyword\": {\n          \"description\": \"可选。只返回原文中包含该关键词的片段及其前后文；不填则按 offset 顺序读取。\",\n          \"type\": \"string\"\n        },\n        \"max_chars\": {\n          \"description\": \"可选。本次最多读取多少字，默认 2000。\",\n          \"maximum\": 2800,\n          \"minimum\": 1,\n          \"type\": \"integer\"\n        },\n        \"offset\": {\n          \"description\": \"可选。从原文第几个字开始读，默认 0；上一次读取会告诉你下一段的 offset。\",\n          \"minimum\": 0,\n          \"type\": \"integer\"\n        },\n        \"result_id\": {\n          \"description\": \"工具返回的原始结果编号，例如 r3。\",\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [\n        \"result_id\"\n      ],\n      \"type\": \"object\"\n    }\n  },\n  \"reply\": {\n    \"description\": \"根据当前思考生成并发送可见回复；可以使用参数附加回复内容。\",\n    \"name\": \"reply\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"attach_emoji\": {\n          \"description\": \"可选。从 show_emoji_list 的拼图选择一个表情包，填写图片序号，在文字后发送；0 或不填表示不发送表情包。\",\n          \"minimum\": 0,\n          \"type\": \"integer\"\n        },\n        \"attach_pic\": {\n          \"default\": [],\n          \"description\": \"可选。随本次回复附加一张或多张上下文图片。每项使用 msg_id + index，或使用 media_index=tool_result:<call_id>:<item_index> 指向工具返回媒体。\",\n          \"items\": {\n            \"properties\": {\n              \"index\": {\n                \"default\": 0,\n                \"description\": \"同一消息中的图片序号，从 0 开始。\",\n                \"type\": \"integer\"\n              },\n              \"media_index\": {\n                \"default\": \"\",\n                \"description\": \"工具返回媒体索引，例如 tool_result:call_x:1；与 msg_id 二选一。\",\n                \"type\": \"string\"\n              },\n              \"msg_id\": {\n                \"default\": \"\",\n                \"description\": \"图片所在的消息编号。\",\n                \"type\": \"string\"\n              }\n            },\n            \"type\": \"object\"\n          },\n          \"type\": \"array\"\n        },\n        \"expression_intent\": {\n          \"description\": \"可选。给 replyer 表达方式选择使用的结构化意图，不是回复正文。当这次回复需要特定语气、场景或话术时填写，避免表达选择只按关键词匹配。\",\n          \"properties\": {\n            \"avoid\": {\n              \"description\": \"需要避免的表达类型、误判方向或不该注入的具体结论。\",\n              \"items\": {\n                \"type\": \"string\"\n              },\n              \"type\": \"array\"\n            },\n            \"focus\": {\n              \"description\": \"本次表达主要应该贴合的目标消息、片段或话题。\",\n              \"type\": \"string\"\n            },\n            \"prefer\": {\n              \"description\": \"优先考虑的表达类型或话术倾向。\",\n              \"items\": {\n                \"type\": \"string\"\n              },\n              \"type\": \"array\"\n            },\n            \"reply_act\": {\n              \"description\": \"这次回复要完成的动作，例如澄清、安抚、调侃、追问、解释边界。\",\n              \"type\": \"string\"\n            },\n            \"scene\": {\n              \"description\": \"当前表达场景，例如技术排查、截图分享、撒娇玩笑、价格询问。\",\n              \"type\": \"string\"\n            },\n            \"tone\": {\n              \"description\": \"期望语气，例如轻松、可靠、吐槽、委婉、简短肯定。\",\n              \"type\": \"string\"\n            }\n          },\n          \"type\": \"object\"\n        },\n        \"msg_id\": {\n          \"description\": \"要回复的消息msg_id。\",\n          \"type\": \"string\"\n        },\n        \"reply_reference\": {\n          \"description\": \"提供本次回复的上下文关键信息与回复方向，包括当前聊天状态、人物关系、事实信息、回忆信息；不是回复正文。\",\n          \"minLength\": 1,\n          \"type\": \"string\"\n        },\n        \"reply_style\": {\n          \"description\": \"可选。控制本次回复的篇幅和表达方式\",\n          \"enum\": [\n            \"简短表达\",\n            \"正常回复\",\n            \"长回复\"\n          ],\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [\n        \"msg_id\",\n        \"reply_reference\"\n      ],\n      \"type\": \"object\"\n    }\n  },\n  \"send_emoji\": {\n    \"description\": \"发送一个表情包来表达情绪，参与聊天。\",\n    \"name\": \"send_emoji\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"msg_id\": {\n          \"description\": \"要回复的消息编号；小黑盒发评论时必须指定主帖或评论消息。\",\n          \"type\": \"string\"\n        }\n      },\n      \"type\": \"object\"\n    }\n  },\n  \"show_emoji_list\": {\n    \"description\": \"查看随机抽取的表情包选择拼图。图片会进入你的上下文，不会发送给聊天对象。调用 reply 时将选中图片的序号填入 attach_emoji；历史拼图的序号也可使用。\",\n    \"name\": \"show_emoji_list\",\n    \"parameters_schema\": {\n      \"properties\": {},\n      \"type\": \"object\"\n    }\n  },\n  \"stop\": {\n    \"description\": \"结束本轮思考并等待新消息，与不调用任何工具时一致；无需继续行动时调用。\",\n    \"name\": \"stop\",\n    \"parameters_schema\": {\n      \"properties\": {},\n      \"required\": [],\n      \"type\": \"object\"\n    }\n  },\n  \"subagent\": {\n    \"description\": \"把一个自包含的查询或整理任务交给子代理。子代理在独立上下文里工作，可以自己多次调用你授权的工具，子代理在后台运行：调用后立刻返回任务 id，你可以继续处理聊天，不需要为它等待；它结束时结论会作为一条 <subagent_result> 消息送回给你，中间的原始结果不会进入你的上下文。需要时用 subagent_status 查看进度，用 subagent_stop 终止不再需要的任务。适合需要多次查询、交叉比对，或会返回大量原始内容的任务；只需要一次简单查询时直接调用对应工具即可。子代理看不到当前聊天，也不能发言：发言、等待和群管理操作必须由你自己完成。\",\n    \"name\": \"subagent\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"task\": {\n          \"description\": \"完整、自包含的任务说明。子代理看不到聊天记录，要写清楚要查什么、相关的名称或关键词、以及你希望得到什么形式的结论。\",\n          \"minLength\": 1,\n          \"type\": \"string\"\n        },\n        \"tools\": {\n          \"description\": \"授权子代理使用的工具名列表，只填查询、检索、读取类工具；可以包含 deferred tools 列表里的工具，不需要先 tool_search。\",\n          \"items\": {\n            \"type\": \"string\"\n          },\n          \"minItems\": 1,\n          \"type\": \"array\"\n        }\n      },\n      \"required\": [\n        \"task\",\n        \"tools\"\n      ],\n      \"type\": \"object\"\n    }\n  },\n  \"subagent_status\": {\n    \"description\": \"查看后台子代理任务的状态。不填 task_id 时列出全部任务；填了则给出该任务的详情，已结束的任务会附上结论。子代理结束时结论会自动送回，一般不需要主动查询。\",\n    \"name\": \"subagent_status\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"task_id\": {\n          \"description\": \"要查看的任务 id，例如 subagent-1；不填则列出全部任务。\",\n          \"type\": \"string\"\n        }\n      },\n      \"type\": \"object\"\n    }\n  },\n  \"subagent_stop\": {\n    \"description\": \"终止一个仍在运行的后台子代理任务。被终止的任务不会再送回结论。\",\n    \"name\": \"subagent_stop\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"task_id\": {\n          \"description\": \"要终止的任务 id，例如 subagent-1。\",\n          \"minLength\": 1,\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [\n        \"task_id\"\n      ],\n      \"type\": \"object\"\n    }\n  },\n  \"tool_search\": {\n    \"description\": \"在 deferred tools 列表中按名称或关键词搜索工具，并将命中的工具加入后续轮次的可用工具列表。\",\n    \"name\": \"tool_search\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"limit\": {\n          \"description\": \"最多返回多少个工具。\",\n          \"minimum\": 1,\n          \"type\": \"integer\"\n        },\n        \"query\": {\n          \"description\": \"要搜索的工具名、前缀或关键词。\",\n          \"type\": \"string\"\n        }\n      },\n      \"required\": [\n        \"query\"\n      ],\n      \"type\": \"object\"\n    }\n  },\n  \"view_forward_message\": {\n    \"description\": \"根据 msg_id 逐层查看合并转发消息。首次调用只展开顶层；遇到嵌套转发时，使用返回内容中的 path 再次调用以继续展开。\",\n    \"name\": \"view_forward_message\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"msg_id\": {\n          \"description\": \"转发消息的 msg_id。\",\n          \"type\": \"string\"\n        },\n        \"path\": {\n          \"description\": \"可选的嵌套转发路径。首次查看时省略，后续使用工具返回内容中的 path 逐层展开。\",\n          \"items\": {\n            \"minimum\": 0,\n            \"type\": \"integer\"\n          },\n          \"type\": \"array\"\n        }\n      },\n      \"required\": [\n        \"msg_id\"\n      ],\n      \"type\": \"object\"\n    }\n  },\n  \"wait\": {\n    \"description\": \"等待一段时间；期间不查看聊天，用于一段时间后再次查看聊天内容。不适用于正在进行的聊天。\",\n    \"name\": \"wait\",\n    \"parameters_schema\": {\n      \"properties\": {\n        \"seconds\": {\n          \"description\": \"等待秒数。\",\n          \"type\": \"integer\"\n        }\n      },\n      \"required\": [\n        \"seconds\"\n      ],\n      \"type\": \"object\"\n    }\n  }\n}"
